async function removeFromPlaceAndDelete(page: Page, name: string) {
  await findProduct(page, name);
  await productRow(page, name).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
  let dlg = page.getByRole('dialog');
  // ждём, пока диалог отрисуется (один из двух вариантов), прежде чем проверять, какой именно
  await expect(
    dlg.getByRole('heading', { name: 'לא ניתן למחוק מוצר עם מלאי' }).or(dlg.getByRole('heading', { name: 'מחיקת מוצר' })),
  ).toBeVisible({ timeout: 20_000 });
  if (await dlg.getByRole('heading', { name: 'לא ניתן למחוק מוצר עם מלאי' }).isVisible().catch(() => false)) {
    await dlg.getByRole('button', { name: 'מעבר למפת המחסן' }).click();
    await expect(page).toHaveURL(/\/warehouse\/map/);
    const item = page.getByRole('listitem').filter({ hasText: name });
    await expect(item).toBeVisible({ timeout: 20_000 });
    await item.getByRole('button', { name: 'הסרה מהמקום' }).click();
    dlg = page.getByRole('dialog');
    await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
    await expect(page.getByRole('listitem').filter({ hasText: name })).toHaveCount(0, { timeout: 15_000 });
    await findProduct(page, name);
    await productRow(page, name).getByRole('button', { name: 'פעולות' }).click();
    await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
    dlg = page.getByRole('dialog');
  }
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  await expect(page.getByText(/הוסר מהקטלוג/)).toBeVisible({ timeout: 15_000 });
}

/** #53ec2724: текст заметки — p[dir=rtl], text-start, прижат вправо; первое (латинское) слово — у правого края. */
async function expectNoteRtl(page: Page) {
  const body = page.getByText(TEAM_NOTE, { exact: true });
  await expect(body).toBeVisible();
  await expect(body).toHaveAttribute('dir', 'rtl');
  await expect(body).toHaveCSS('direction', 'rtl');
  const m = await body.evaluate((el) => {
    const cs = getComputedStyle(el);
    const box = el.getBoundingClientRect();
    const all = document.createRange();
    all.selectNodeContents(el);
    const t = all.getBoundingClientRect();
    const node = el.firstChild!;
    const firstWord = document.createRange();
    firstWord.setStart(node, 0);
    firstWord.setEnd(node, (node.textContent ?? '').indexOf(' '));
    const fw = firstWord.getBoundingClientRect();
    return { align: cs.textAlign, boxRight: box.right, textRight: t.right, textLeft: t.left, boxLeft: box.left, firstRight: fw.right };
  });
  expect(['start', 'right']).toContain(m.align);
  expect(Math.abs(m.boxRight - m.textRight), 'текст прижат к правому краю блока').toBeLessThanOrEqual(2);
  expect(Math.abs(m.boxRight - m.firstRight), 'первое слово заметки (латиница) — справа').toBeLessThanOrEqual(2);
}

